/**
 * Channel helpers shared by the admin app and the frontend widget.
 *
 * Pure functions only (no globals), so both bundles can import them.
 *
 * @since 2.16.0
 */

export const CONFIG_VERSION = 2

export const CHANNELS = ['whatsapp', 'telegram']

// Brand colors used for channel buttons and headers.
export const CHANNEL_COLORS = {
    whatsapp: '#25D366',
    telegram: '#229ED9',
}

// Every channel list style a widget may save. Mirrors App::LIST_STYLES in PHP.
export const LIST_STYLES = ['stack', 'card', 'row', 'chat', 'grid', 'bubble', 'menu', 'corner']

// Channel icon color presets (2.16.0). An empty saved color means the brand color.
export const CHANNEL_COLOR_PRESETS = ['#4F46E5', '#111827', '#0F766E', '#E11D48', '#F59E0B']

// Channel glyph (logo mark) color presets; the admin adds the channel's brand color after the first one.
// An empty saved color means white.
export const CHANNEL_GLYPH_COLOR = '#FFFFFF'
export const CHANNEL_GLYPH_PRESETS = ['#111827', '#4F46E5', '#E11D48', '#F59E0B']

export const isHexColor = value => /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(value ?? ''))

/**
 * Color of a channel's icon: the saved `icon_color`, else the brand color.
 *
 * @param {object} config  Widget config (raw or normalized).
 * @param {string} channel whatsapp | telegram.
 * @returns {string}
 */
export const channelIconColor = (config, channel) => {
    const saved = config?.[channel]?.icon_color
    return isHexColor(saved) ? saved : (CHANNEL_COLORS[channel] || CHANNEL_COLORS.whatsapp)
}

/**
 * Color of a channel's logo glyph: the saved `glyph_color`, else white.
 *
 * @param {object} config  Widget config (raw or normalized).
 * @param {string} channel whatsapp | telegram.
 * @returns {string}
 */
export const channelGlyphColor = (config, channel) => {
    const saved = config?.[channel]?.glyph_color
    return isHexColor(saved) ? saved : CHANNEL_GLYPH_COLOR
}

/**
 * Image the admin saved for a channel's icon, or '' while the channel's own logo is used.
 * WhatsApp keeps `icon.image_url` (the default whatsapp.svg counts as no image); Telegram uses `telegram.icon_url`.
 * Admin only: on the site, uploaded images arrive resolved through `formychat_channel_icon_url`.
 *
 * @param {object} config  Widget config.
 * @param {string} channel whatsapp | telegram.
 * @returns {string}
 */
export const savedChannelImage = (config, channel) => {
    if (channel === 'whatsapp') {
        const url = String(config?.icon?.image_url || '')
        return url && !/\/images\/whatsapp\.svg$/.test(url) ? url : ''
    }
    return String(config?.[channel]?.icon_url || '')
}

export const CHANNEL_DEFAULTS = {
    channels: {
        enabled: ['whatsapp'],
        launcher: {
            style: 'stack',
            title: 'How would you like to reach us?',
            show_sub: true,
            icon: 'chat',
            color: '#4F46E5',
            // 2.16.0 additions; empty keeps today's look.
            message: '',
            header_color: '',
            icon_url: '',
            // Color of the launcher symbol; '' = white (today's look).
            glyph_color: '',
        },
    },
    delivery: {
        redirect_after_submit: true,
    },
    whatsapp: {
        show_on_desktop: true,
        show_on_mobile: true,
        list_label: 'WhatsApp',
        list_sub: 'Chat on WhatsApp',
        icon_color: '',
        glyph_color: '',
    },
    telegram: {
        mode: 'username',
        username: '',
        country_code: '',
        phone: '',
        new_tab: true,
        web_fallback: true,
        show_on_desktop: true,
        show_on_mobile: true,
        list_label: 'Telegram',
        list_sub: 'Message us on Telegram',
        form_title: 'Contact via Telegram',
        form_submit: 'Send on Telegram',
        icon_color: '',
        glyph_color: '',
        icon_url: '',
    },
}

const isMap = value => value !== null && typeof value === 'object' && !Array.isArray(value)

const clone = value => JSON.parse(JSON.stringify(value))

/**
 * Treats false / 0 / "0" / "false" / "" as off, like wp_validate_boolean().
 */
export const toBool = (value) => {
    if (value === false || value === 0 || value === '0' || value === 'false' || value === '' || value === null || value === undefined) {
        return false
    }
    return true
}

/**
 * Fill keys missing from a saved config with defaults. Saved values win,
 * unknown keys are kept, and lists are never merged by index.
 */
export const mergeDefaults = (defaults, saved) => {
    if (!isMap(saved)) {
        return clone(defaults)
    }

    const merged = { ...saved }

    Object.keys(defaults).forEach((key) => {
        if (!(key in merged) || merged[key] === undefined) {
            merged[key] = clone(defaults[key])
            return
        }

        if (isMap(defaults[key])) {
            // A section saved as null, a list or a scalar is replaced, like the PHP normalizer does.
            merged[key] = isMap(merged[key]) ? mergeDefaults(defaults[key], merged[key]) : clone(defaults[key])
        }
    })

    return merged
}

/**
 * Bare Telegram username from whatever was pasted (@name, t.me/name, https://telegram.me/name/).
 */
export const cleanTelegramUsername = (value = '') => {
    let clean = String(value ?? '').trim()
    clean = clean.replace(/^https?:\/\//i, '')
    clean = clean.replace(/^(www\.)?(t|telegram)\.me\//i, '')
    clean = clean.replace(/^@+/, '')
    clean = clean.split(/[/?#]/)[0] || ''

    return clean.replace(/[^A-Za-z0-9_]/g, '')
}

export const isValidTelegramUsername = (username = '') => /^[A-Za-z][A-Za-z0-9_]{3,30}[A-Za-z0-9]$/.test(username)

export const digitsOnly = (value = '') => String(value ?? '').replace(/\D/g, '')

/**
 * Upgrade a widget config to the channels schema, in memory only.
 * Mirrors App::normalize_widget_config() in PHP. Idempotent.
 *
 * @param {object} config Saved widget config.
 * @returns {object} New config object; the input is not changed.
 */
export const normalizeConfig = (config) => {
    let next = isMap(config) ? { ...config } : {}
    const version = Number(next.config_version) || 1

    next = mergeDefaults(CHANNEL_DEFAULTS, next)

    if (version < CONFIG_VERSION) {
        next.channels.enabled = ['whatsapp']
        next.delivery.redirect_after_submit = next.whatsapp && 'send_message_to_whatsapp' in next.whatsapp
            ? toBool(next.whatsapp.send_message_to_whatsapp)
            : true
        next.config_version = CONFIG_VERSION
    }

    const enabled = Array.isArray(next.channels.enabled) ? next.channels.enabled : []
    const clean = enabled.filter((channel, index) => CHANNELS.includes(channel) && enabled.indexOf(channel) === index)
    next.channels.enabled = clean.length ? clean : ['whatsapp']

    if (isMap(next.channels.launcher) && !LIST_STYLES.includes(next.channels.launcher.style)) {
        next.channels.launcher.style = 'stack'
    }

    // Launcher symbol color (2.16.0): a valid hex or empty (white).
    if (isMap(next.channels.launcher) && !isHexColor(next.channels.launcher.glyph_color)) {
        next.channels.launcher.glyph_color = ''
    }

    next.delivery.redirect_after_submit = toBool(next.delivery.redirect_after_submit)
    next.telegram.username = cleanTelegramUsername(next.telegram.username)

    // Channel icon colors (2.16.0): a valid hex or empty (brand color).
    CHANNELS.forEach((channel) => {
        if (!isHexColor(next[channel].icon_color)) {
            next[channel].icon_color = ''
        }
        if (!isHexColor(next[channel].glyph_color)) {
            next[channel].glyph_color = ''
        }
    })

    // Per-channel "open the chat app" (2.16.0). A channel without its own value
    // inherits the widget-wide one, so older widgets behave exactly as before.
    CHANNELS.forEach((channel) => {
        next[channel].redirect_after_submit = 'redirect_after_submit' in next[channel]
            ? toBool(next[channel].redirect_after_submit)
            : next.delivery.redirect_after_submit
    })

    // Keep the old WhatsApp-only key in sync.
    next.whatsapp.send_message_to_whatsapp = next.whatsapp.redirect_after_submit

    return next
}

/**
 * Whether a channel opens its chat app after the form is sent.
 * Works on a saved (raw) or a normalized config, with the same fallbacks
 * as normalizeConfig(): channel value, then widget-wide value, then the
 * legacy WhatsApp key.
 *
 * @param {object} config  Widget config.
 * @param {string} channel whatsapp | telegram.
 * @returns {boolean}
 */
export const redirectsAfterSubmit = (config, channel = 'whatsapp') => {
    const settings = config?.[channel]
    if (isMap(settings) && 'redirect_after_submit' in settings) {
        return toBool(settings.redirect_after_submit)
    }

    const version = Number(config?.config_version) || 1
    if (version >= CONFIG_VERSION) {
        return isMap(config?.delivery) && 'redirect_after_submit' in config.delivery
            ? toBool(config.delivery.redirect_after_submit)
            : true
    }

    const whatsapp = config?.whatsapp
    return isMap(whatsapp) && 'send_message_to_whatsapp' in whatsapp
        ? toBool(whatsapp.send_message_to_whatsapp)
        : true
}

/**
 * Whether a channel has somewhere to send the visitor.
 */
export const hasDestination = (config, channel) => {
    if (channel === 'telegram') {
        const telegram = config?.telegram || {}
        return telegram.mode === 'phone'
            ? /^\d{7,15}$/.test(String(telegram.phone || ''))
            : isValidTelegramUsername(cleanTelegramUsername(telegram.username))
    }

    // WhatsApp keeps working exactly as before, even without a number.
    return true
}

/**
 * Channels to show for this visitor, in the admin's order.
 *
 * @param {object}  config    Normalized widget config.
 * @param {boolean} onDesktop Whether the visitor is on a desktop device.
 * @returns {string[]}
 */
export const CHANNEL_NAMES = { whatsapp: 'WhatsApp', telegram: 'Telegram' }

/**
 * Channel name as the admin set it: '' when they cleared it on purpose (`show_label: false`).
 * An empty name saved before 2.16.0 (no `show_label`) still shows the channel's own name.
 */
export const channelLabel = (config, channel) => {
    const settings = config?.[channel] || {}
    if (settings.show_label === false) return ''
    return String(settings.list_label || '').trim() || CHANNEL_NAMES[channel] || channel
}

/**
 * Name for a row in a list or panel: never empty, so a row is not just a bare icon.
 */
export const channelRowLabel = (config, channel) => channelLabel(config, channel) || CHANNEL_NAMES[channel] || channel

/**
 * Save the Channel name field. Clearing it hides the name next to the icon.
 */
export const setChannelLabel = (config, channel, value) => {
    if (!config?.[channel]) return
    const text = String(value ?? '')
    config[channel].list_label = text
    config[channel].show_label = text.trim() !== ''
}

export const getEnabledChannels =(config, onDesktop = true) => {
    const enabled = config?.channels?.enabled || ['whatsapp']

    return enabled.filter((channel) => {
        const settings = config?.[channel] || {}

        if (onDesktop && settings.show_on_desktop === false) return false
        if (!onDesktop && settings.show_on_mobile === false) return false

        return hasDestination(config, channel)
    })
}

/**
 * wa.me (or WhatsApp Web) link. Output is identical to FormyChat before 2.16.0.
 */
export const buildWhatsappUrl = (to, text = '', useWeb = false) => {
    if (useWeb) {
        return `https://web.whatsapp.com/send?phone=${to}&text=${encodeURIComponent(text)}`
    }

    return `https://wa.me/${to}?text=${encodeURIComponent(text)}`
}

// Keep links short enough for every browser and the Telegram apps.
export const TELEGRAM_URL_LIMIT = 2000

const telegramTarget = (telegram = {}) => {
    if (telegram.mode === 'phone') {
        return { phone: digitsOnly(telegram.country_code) + digitsOnly(telegram.phone) }
    }
    return { username: cleanTelegramUsername(telegram.username) }
}

/**
 * Trim the message until the encoded link fits the limit.
 */
const fitText = (build, text = '') => {
    if (build(text).length <= TELEGRAM_URL_LIMIT) {
        return text
    }

    // Binary search the longest prefix that fits, then mark it as cut.
    let low = 0
    let high = text.length
    while (low < high) {
        const mid = Math.ceil((low + high) / 2)
        if (build(text.slice(0, mid) + '…').length <= TELEGRAM_URL_LIMIT) {
            low = mid
        } else {
            high = mid - 1
        }
    }

    return text.slice(0, low) + '…'
}

/**
 * t.me link that opens the chat with the message typed in.
 *
 * @param {object} telegram Telegram settings from the widget config.
 * @param {string} text     Message.
 * @returns {string}
 */
export const buildTelegramUrl = (telegram, text = '') => {
    const target = telegramTarget(telegram)
    const base = target.phone ? `https://t.me/+${target.phone}` : `https://t.me/${target.username}`

    if (!text) {
        return base
    }

    const build = value => `${base}?text=${encodeURIComponent(value)}`

    return build(fitText(build, text))
}

/**
 * Telegram Web link, used as a fallback on desktop when the app is not installed.
 * Same Web K address the t.me page itself offers ("Open in Web").
 */
export const buildTelegramWebUrl = (telegram, text = '') => {
    const target = telegramTarget(telegram)
    const base = target.phone ? `tg://resolve?phone=${target.phone}` : `tg://resolve?domain=${target.username}`

    const build = value => `https://web.telegram.org/k/#?tgaddr=${encodeURIComponent(value ? `${base}&text=${encodeURIComponent(value)}` : base)}`

    return text ? build(fitText(build, text)) : build('')
}
