                                class="w-full mx-auto" /> </div>
                        <!-- CTA  -->
                        <div v-if="wave.show_cta" class="formychat-widget-greetings-wave-2-cta"
                            :style="{ background: wave.cta_background_color }">
                            <!-- heading  -->
                            <div class="formychat-widget-greetings-wave-2-cta-heading" v-if="wave.cta_heading" x-text=""
                                :style="{ color: wave.cta_heading_color, fontSize: getSize(wave.cta_heading_size, wave.cta_heading_size_custom) }">
                                {{ wave.cta_heading }} </div>
                            <!-- message  -->
                            <div class="formychat-widget-greetings-wave-2-cta-message" v-if="wave.cta_message"
                                :style="{ color: wave.cta_message_color, fontSize: getSize(wave.cta_message_size, wave.cta_message_size_custom) }">
                                {{ wave.cta_message }} </div>
                        </div>
                        <!-- Main icon - After CTA  -->
                        <div v-if="wave.show_icon && wave.icon_position === 'after_cta'"
                            class="formychat-widget-greetings-wave-2-icon"> <img :src="wave.icon_url"
                                class="w-full mx-auto" /> </div>
                    </div>
                </div>
            </div>
        </transition>
        <!-- channel list drawn by a registered style (window.formychat_list_styles); FormyChat only provides the box -->
        <div v-if="isMulti && listRenderer" ref="listHost" class="formychat-channel-host"
            :class="{ 'is-open': state.showList }" :data-style="listStyle" :data-position="icon.position === 'left' ? 'left' : 'right'"
            :aria-hidden="state.showList ? 'false' : 'true'" :style="{ '--fc-launcher': launcherSize }"></div>
        <!-- icon box  -->
        <transition name="bounce" >
            <div v-if="state.showIcon" tabindex="0" class="formychat-widget-handler group" :class="{ 'reversed': icon.position === 'left' }"
                @click.prevent="onLauncherClick()">
                <!-- cta  -->
                <transition name="bounce">
                    <div v-if="cta.enabled" class="formychat-widget-handler-cta"
                        :style="{ color: cta.color, background: cta.background_color, fontSize: getSize(cta.size, cta.size_custom, headingSizes) }">
                        {{ cta.text }} </div>
                </transition>
                <!-- icon  -->
                <div v-if="!isMulti" class="formychat-widget-handler-icon group-hover:opacity-95 group-hover:scale-110"
                    :style="{ width: getSize(icon.size, icon.size_custom, iconSizes), height: getSize(icon.size, icon.size_custom, iconSizes) }">
                    <span v-if="singleIcon.color" class="formychat-widget-handler-icon-color" :style="{ background: singleIcon.color }">
                        <span class="formychat-channel-glyph" :style="glyphStyle(singleIcon.channel)" aria-hidden="true"></span>
                    </span>
                    <img v-else :src="singleIcon.url">
                </div>
                <!-- launcher for several channels: its icon only, the channels show on click -->
                <div v-else class="formychat-launcher" :class="{ 'is-open': state.showList, 'is-active': state.showModal }">
                    <ul v-if="listStyle === 'stack'" class="formychat-channel-stack" :aria-hidden="!state.showList"
                        :style="{ '--fc-launcher': launcherSize }">
                        <li v-for="(channel, index) in channels" :key="channel" :style="{ '--fc-i': index }">
                            <button type="button" class="formychat-channel-stack-item" :tabindex="state.showList ? 0 : -1"
                                @click.stop="pickChannel(channel)">
                                <span v-if="channelShowsLabel(channel)" class="formychat-channel-stack-label">{{ channelName(channel) }}</span>
                                <span class="formychat-channel-stack-button" :class="{ 'has-image': channelImage(channel) }"
                                    :style="channelImage(channel) ? {} : { background: channelColor(channel) }">
                                    <img v-if="channelImage(channel)" :src="channelImage(channel)" alt="">
                                    <span v-else class="formychat-channel-glyph" :style="glyphStyle(channel)" aria-hidden="true"></span>
                                </span>
                            </button>
                        </li>
                    </ul>
                    <button type="button" class="formychat-launcher-button" :class="[`formychat-launcher-button--${launcherShape}`, { 'has-image': customLauncherUrl }]"
                        :aria-expanded="state.showList ? 'true' : 'false'"
                        :aria-label="state.showList ? strings.close : strings.open_list"
                        :style="{ width: launcherSize, height: launcherSize, background: launcher.color, '--fc-launcher-h': launcherSize }">
                        <span v-if="launcherShape === 'pill'" class="formychat-launcher-icon formychat-launcher-pill" :style="launcherGlyphColor ? { color: launcherGlyphColor } : {}">
                            <span v-if="launcherGlyphColor" class="formychat-launcher-glyph" :style="{ ...launcherGlyphStyle, display: 'inline-block', width: '22px', height: '22px', flex: 'none' }" aria-hidden="true"></span>
                            <img v-else :src="launcherIconUrl" alt="">{{ launcherIconData.text }}
                        </span>
                        <span v-else-if="launcherGlyphColor" class="formychat-launcher-icon formychat-launcher-glyph" :style="[launcherGlyphStyle, launcherIconBox]" aria-hidden="true"></span>
                        <img v-else class="formychat-launcher-icon" :style="launcherIconBox" :src="launcherIconUrl" alt="">
                        <svg class="formychat-launcher-close" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" :stroke="launcherGlyphColor || '#fff'" stroke-width="2.2" stroke-linecap="round" aria-hidden="true">
                            <path d="M6 6l12 12M18 6 6 18" />
                        </svg>
                    </button>
                </div>
            </div>
        </transition>
    </div>
</template>

<script setup>
import { ref, computed, onMounted, reactive, watch } from 'vue';
import Select from './../admin/components/Select.vue';
import { isLocked, countries, getMeta, headingSizes, iconSizes, getSize, save, getMessage, isDesktop, openWhatsapp, openChannel, shouldRedirect, normalizeConfig, getEnabledChannels, buildTelegramUrl, buildTelegramWebUrl, CHANNEL_COLORS } from './store'
import { channelIconColor, channelGlyphColor } from './../admin/utility/channels.js'

function mergeCustomDropdownIntoFields(baseFields, formConfig) {
    const cd = formConfig?.custom_dropdown
    if (!cd?.enabled || !Array.isArray(cd.options) || !cd.options.length) {
        return baseFields
    }
    const name = cd.name || 'dropdown'
    const selectField = {
        name,
        type: 'select',
        label: cd.label || '',
        default: cd.default_value || '',
        options: cd.options.map((o) => ({ value: o.value, label: o.label })),
        attributes: {
            required: !!cd.required,
            placeholder: cd.placeholder || '',
        },
    }
    const list = [...baseFields]
    const pos = cd.position || 'before_message'
    let insertAt = list.length
    if (pos === 'before_message') {
        const i = list.findIndex((f) => f.name === 'message')
        insertAt = i === -1 ? list.length : i
    } else if (pos === 'after_name') {
        const i = list.findIndex((f) => f.name === 'name')
        insertAt = i === -1 ? list.length : i + 1
    } else if (pos === 'after_email') {
        const i = list.findIndex((f) => f.name === 'email')
        insertAt = i === -1 ? list.length : i + 1
    } else if (pos === 'after_phone') {
        const i = list.findIndex((f) => f.name === 'phone')
        insertAt = i === -1 ? list.length : i + 1
    }
    list.splice(insertAt, 0, selectField)
    return list
}

const props = defineProps({
    widget: {
        type: Object,
        default: () => { }
    }
});

// Channel settings upgraded in memory, in case the page was cached before 2.16.0.
const channelConfig = computed(() => normalizeConfig(props.widget.config))

const whatsapp = computed(() => channelConfig.value.whatsapp || {});
const telegram = computed(() => channelConfig.value.telegram || {});
const launcher = computed(() => channelConfig.value.channels?.launcher || {});
const form = computed(() => props.widget.config.form || {});

const vars = typeof formychat_vars !== 'undefined' ? formychat_vars : {}
const strings = Object.assign({
    opening: 'Opening %s',
    opening_hint: 'If nothing opened, use the button below. Your message is ready to send.',
    open_app: 'Open %s',
    open_web: 'Open Telegram Web',
    copy: 'Copy message',
    copied: 'Copied',
    back: 'Back',
    close: 'Close',
    open_list: 'Open contact options',
}, vars.channel_strings || {})
const images = vars.images || {}
const sprintf = (text = '', value = '') => String(text).replace('%s', value)

// Channels this visitor can use, in the admin's order.
const channels = computed(() => getEnabledChannels(channelConfig.value, isDesktop()))
const isMulti = computed(() => channels.value.length > 1)

// Narrow screens open the form of a multi-channel widget as a bottom sheet.
const isPhoneScreen = typeof window !== 'undefined' && window.matchMedia ? window.matchMedia('(max-width: 480px)').matches : false

// Display only: whether the visitor is sent to the chat app of the active channel after submit.
const redirectsAfterSubmit = computed(() => channelConfig.value[activeChannel.value]?.redirect_after_submit !== false)

const channelName = (channel) => channelConfig.value[channel]?.list_label || (channel === 'telegram' ? 'Telegram' : 'WhatsApp')
// The name next to a floating icon: hidden when the admin cleared the Channel name (2.16.0).
const channelShowsLabel = (channel) => channelConfig.value[channel]?.show_label !== false
const channelSub = (channel) => channelConfig.value[channel]?.list_sub || ''
// Icons resolved on the server (2.16.0): uploaded images come from FormyChat Ultimate through
// `formychat_channel_icon_url` / `formychat_launcher_icon_url`; empty means FormyChat's own icon.
const resolved = computed(() => props.widget.resolved || {})
// The admin's channel color (free), else the brand color.
const channelColor = (channel) => channelIconColor(channelConfig.value, channel)
const channelGlyph = (channel) => images[`${channel}_glyph`] || ''
const channelImage = (channel) => resolved.value.channel_icons?.[channel] || ''
// Logo glyph color (free; '' saved = white).
const glyphColor = (channel) => channelGlyphColor(channelConfig.value, channel)
// The glyph tinted through a CSS mask, so any color works with the one white SVG.
const glyphStyle = (channel) => {
    const url = String(channelGlyph(channel)).replace(/["\\\s]/g, encodeURIComponent)
    const mask = `url("${url}") center / contain no-repeat`
    return { backgroundColor: glyphColor(channel), WebkitMask: mask, mask }
}

// Channel list styles. FormyChat draws Buttons (`stack`). Other styles are drawn by code
// that registers a renderer in `window.formychat_list_styles` and then fires `formychat_list_styles_ready`;
// with no renderer for the saved style, Buttons shows.
const listRenderers = ref({})
const loadListRenderers = () => {
    const registry = typeof window !== 'undefined' ? window.formychat_list_styles : null
    listRenderers.value = registry && typeof registry === 'object' ? { ...registry } : {}
}
loadListRenderers()
if (typeof document !== 'undefined') {
    document.addEventListener('formychat_list_styles_ready', loadListRenderers)
}
const listStyle = computed(() => {
    const style = launcher.value.style
    if (style === 'stack') return style
    return typeof listRenderers.value[style] === 'function' ? style : 'stack'
})
const listRenderer = computed(() => listStyle.value === 'stack' ? null : listRenderers.value[listStyle.value])

const formSubmitButtonLabel = computed(() => {
    if (!redirectsAfterSubmit.value) {
        return vars.form_submit_label || 'Submit'
    }
    if (activeChannel.value === 'telegram') {
        return telegram.value.form_submit || form.value.submit
    }
    return form.value.submit
})

const formTitle = computed(() => activeChannel.value === 'telegram' ? (telegram.value.form_title || form.value.title) : form.value.title)

// WhatsApp keeps the admin's form colors; Telegram uses its brand color.
const headerStyle = computed(() => {
    if (activeChannel.value === 'telegram') {
        return { color: '#ffffff', background: CHANNEL_COLORS.telegram }
    }
    return { color: form.value.text_color, background: form.value.background_color }
})

const icon = computed(() => props.widget.config.icon || {});
const cta = computed(() => props.widget.config.cta || {});
const cf7 = computed(() => props.widget.config.cf7 || {});

const greetings = computed(() => props.widget.config.greetings || {});
const simple = computed(() => greetings.value.templates.simple || {});
const wave = computed(() => greetings.value.templates.wave || {});
const whatsappNumber = computed(() => whatsapp.value.country_code + whatsapp.value.number || '');
const whatsappTo = computed(() => {
    // Group destination is a FormyChat Ultimate feature.
    if (formychat_vars.is_premium && whatsapp.value.destination_type === 'group' && whatsapp.value.group_invite_code) {
        return whatsapp.value.group_invite_code;
    }
    return whatsappNumber.value;
});

const iconPosition = computed(() => {
    if (icon.value.position !== 'custom') return {};

    return {
        top: icon.value.position_custom?.top ? icon.value.position_custom?.top + 'px !important' : 'auto',
        bottom: icon.value.position_custom?.bottom ? icon.value.position_custom?.bottom + 'px !important' : 'auto',
        left: icon.value.position_custom?.left ? icon.value.position_custom?.left + 'px !important' : 'auto',
        right: icon.value.position_custom?.right ? icon.value.position_custom?.right + 'px !important' : 'auto',
    };
})

const shouldShowWidget = computed(() => {
    if (!channels.value.length) return false
    const onDesktop = isDesktop()
    if (onDesktop && icon.value.show_on_desktop === false) return false
    if (!onDesktop && icon.value.show_on_mobile === false) return false
    return true
})

// When to show form.
const state = reactive({
    showIcon: false,
    open: false,
    agent: whatsapp.value.agent_mode === 'agents' ? null : true,
    showList: false,
    channel: null,
    sent: null,
    copied: false,
    greetings: true,
    submitted: false,
    errors: [],
    sending: false,
    recaptchaError: null,
})

// The channel the visitor picked; with one channel it is that channel.
const activeChannel = computed(() => {
    if (state.channel && channels.value.includes(state.channel)) return state.channel
    return channels.value[0] || 'whatsapp'
})

const launcherSize = computed(() => getSize(icon.value.size, icon.value.size_custom, iconSizes))

const launcherIcons = vars.data?.launcher_icons || {}
const launcherIconData = computed(() => launcherIcons[launcher.value.icon] || launcherIcons.chat || {})
// Icon size in % of the launcher, set per icon (Form and Sparkle chat are drawn larger, as in their design).
const launcherIconBox = computed(() => {
    const box = Number(launcherIconData.value.box)
    return box && box !== 46 ? { width: box + '%', height: box + '%' } : null
})
const customLauncherUrl = computed(() => resolved.value.launcher_icon_url || '')
const launcherIconUrl = computed(() => customLauncherUrl.value || launcherIconData.value.url || '')
// An uploaded launcher image is always round.
const launcherShape = computed(() => customLauncherUrl.value ? 'circle' : (launcherIconData.value.shape || 'circle'))
// Launcher symbol color from `formychat_launcher_glyph_color` ('' = white, drawn as before).
// An uploaded launcher image is shown as is.
const launcherGlyphColor = computed(() => {
    const color = String(resolved.value.launcher_glyph_color || '')
    return !customLauncherUrl.value && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(color) ? color : ''
})
// The preset icon tinted through a CSS mask, like the channel glyphs.
const launcherGlyphStyle = computed(() => {
    const url = String(launcherIconUrl.value).replace(/["\\\s]/g, encodeURIComponent)
    const mask = `url("${url}") center / contain no-repeat`
    return { backgroundColor: launcherGlyphColor.value, WebkitMask: mask, mask }
})

// Single channel: the button is that channel's icon.
// WhatsApp keeps `icon.image_url` exactly as before; Telegram uses its uploaded icon (FormyChat Ultimate) or its logo.
// With a background or icon color and no image, the glyph is drawn on a circle of that color.
const singleIcon = computed(() => {
    const channel = activeChannel.value
    const glyph = channelGlyph(channel)
    const settings = channelConfig.value[channel] || {}
    const ownColor = settings.icon_color || settings.glyph_color ? channelColor(channel) : ''

    if (channel === 'telegram') {
        const image = channelImage('telegram')
        if (image) return { url: image, color: '' }
        if (ownColor && glyph) return { url: '', color: ownColor, glyph, channel }
        return { url: images.telegram || '', color: '' }
    }

    const url = icon.value.image_url || images.whatsapp || vars.data?.default_config?.icon?.image_url || ''
    // The default icon is saved with the plugin's URL at save time; use the current one so moved sites keep it.
    if (/\/images\/whatsapp\.svg$/.test(url)) {
        if (ownColor && glyph) return { url: '', color: ownColor, glyph, channel }
        return { url: images.whatsapp || url, color: '' }
    }
    return { url, color: '' }
})

const dispatchEvent = (event, detail = {}) => {
    const newEvent = new CustomEvent(event, { detail });
    const dispatched = document.dispatchEvent(newEvent);
    return dispatched;
}

// Show the widget. Trigger behaviour (delay / scroll / exit-intent) is provided
// by FormyChat Ultimate, which listens for the event dispatched below.
const showWidget = async () => {
    // Show form, if form is requested to show by default.
    if (form.value.open_by_default) {
        state.showModal = true;
        dispatchEvent('formychat_widget_opened', { widget_id: props.widget.id })
    }

    /**
     * Ultimate hooks this to apply Time Delay / Page Scroll / Exit Intent
     * triggers. It receives the widget config and a small control object and
     * decides when to set state.showIcon. If nothing handles it, the widget
     * shows immediately (free behaviour).
     */
    const handled = document.dispatchEvent(new CustomEvent('formychat_widget_before_show', {
        cancelable: true,
        detail: {
            widget: props.widget,
            show: () => {
                state.showIcon = true;
                dispatchEvent('formychat_widget_opened', { widget_id: props.widget.id })
            },
            hide: () => {
                state.showIcon = false;
                dispatchEvent('formychat_widget_closed', { widget_id: props.widget.id })
            },
        },
    }));

    // dispatchEvent returns false if a listener called preventDefault() — i.e.
    // Ultimate is handling the trigger timing. Otherwise show now.
    if ( handled ) {
        state.showIcon = true;
        dispatchEvent('formychat_widget_opened', { widget_id: props.widget.id })
    }
}
onMounted(() => {
    showWidget()
    if ( cf7.value.form_id ) {
        form.value.cf7_id = cf7.value.form_id
        // Reset cf7_id.
        cf7.value.form_id = ''
    }
})

/**
 * Form related functions.
 */
const closePopup = () => {
    state.showModal = false;
    state.formLoaded = false;
    state.showList = false;
    state.sent = null;
    dispatchEvent('formychat_widget_closed', { widget_id: props.widget.id })
}

/**
 * Channel list (widgets with several channels).
 */
const openList = () => {
    state.greetings = false;
    state.showModal = false;
    state.sent = null;
    state.showList = true;
    dispatchEvent('formychat_widget_opened', { widget_id: props.widget.id })
}

const closeList = () => {
    state.showList = false;
}

const onLauncherClick = () => {
    if (!isMulti.value) {
        return state.showModal ? closePopup() : openPopup()
    }

    // The launcher turns into a close button while the list or a form is open.
    if (state.showList || state.showModal) {
        return closePopup()
    }

    openList()
}

const pickChannel = async (channel) => {
    state.channel = channel
    state.showList = false
    dispatchEvent('formychat_channel_selected', { widget_id: props.widget.id, channel })
    await openPopup(0)
}

const backToList = () => {
    state.showModal = false;
    state.formLoaded = false;
    state.sent = null;
    state.showList = true;
}

// A registered style fills the box once; FormyChat toggles `is-open` on it with the list.
const listHost = ref(null)
let listCleanup = null
watch([listHost, listRenderer], ([host, render]) => {
    if (typeof listCleanup === 'function') listCleanup()
    listCleanup = null
    if (!host || typeof render !== 'function') return
    host.innerHTML = ''
    try {
        listCleanup = render({
            el: host,
            style: listStyle.value,
            widgetId: props.widget.id,
            position: icon.value.position === 'left' ? 'left' : 'right',
            title: launcher.value.title || '',
            // 2.16.0: text under the title and the Chat window header color (empty = renderer default).
            message: launcher.value.message || '',
            headerColor: launcher.value.header_color || '',
            showSub: launcher.value.show_sub !== false,
            accent: launcher.value.color || CHANNEL_COLORS.whatsapp,
            launcherSize: launcherSize.value,
            strings: { close: strings.close },
            channels: channels.value.map(channel => ({
                key: channel,
                label: channelName(channel),
                // 2.16.0: false when the admin cleared the name; floating styles then show no name tip.
                showLabel: channelShowsLabel(channel),
                sub: channelSub(channel),
                color: channelColor(channel),
                glyph: channelGlyph(channel),
                // Logo glyph color: a valid hex, '#FFFFFF' by default.
                glyphColor: glyphColor(channel),
                // 2.16.0: uploaded image for this channel ('' = draw `glyph` on `color`), and the brand color.
                icon: channelImage(channel),
                brandColor: CHANNEL_COLORS[channel] || CHANNEL_COLORS.whatsapp,
            })),
            pick: channel => channels.value.includes(channel) && pickChannel(channel),
            close: () => closeList(),
        })
    } catch (e) {
        // A broken style falls back to Buttons.
        host.innerHTML = ''
        delete listRenderers.value[listStyle.value]
    }
}, { flush: 'post' })


const openPopup = async (delay = 210) => {
    return new Promise(async (resolve) => {
        state.greetings = false;
        state.agent = null;
        state.errors = [];
        state.sent = null;
        setTimeout(async () => {
            state.showModal = true;
            dispatchEvent('formychat_widget_opened', { widget_id: props.widget.id })
            resolve(true);
        }, (state.greetings) ? delay : 0)
    })
}

/**
 * Greetings related functions.
 */
const clickedGreetings = async () => {
    if (!state.greetings) return;

    if (greetings.value.on_click === 'list' && isMulti.value) {
        openList()
    } else if (greetings.value.on_click === 'show_form' || greetings.value.on_click === 'list') {
        // The form of the first channel (the only one, or the top of the list).
        await openPopup()
    } else {
        if (isLocked) return;
        openChannel(activeChannel.value, {
            config: channelConfig.value,
            to: whatsappTo.value,
            isWeb: isDesktop() && whatsapp.value.web_version,
            newTab: whatsapp.value.new_tab,
        })
    }
}

const theForm = ref(null)
onMounted(() => {
    // Anywhere clicked but theForm, will close the form.
    window.addEventListener('click', (e) => {
        // Clicks outside the widget close the channel list.
        if (state.showList && !e.target.closest('#formychat-widget-' + props.widget.id)) {
            closeList()
        }

        if (!theForm.value || !state.showModal) return;

        // If clicked outside the theForm, not containing theForm  or not theForm's child, then hide theForm.
        if (!theForm.value.contains(e.target) && !e.target.closest('.formychat-widget-agents')) {
            closePopup()
        }
    })

    // Anywhere pressed ESC key, will close the form.
    window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            if (state.showList) {
                closeList()
                return
            }
            closePopup()
        }
    })

})

const buildDefaultFormData = (fieldsList) => {
    const data = {}
    fieldsList.forEach((field) => {
        data[field.name] = field.default !== undefined && field.default !== null ? field.default : ''
    })
    return data
}

const formychat_fields = computed(() => {
    const base = formychat_vars.data.form_fields || []
    if (form.value.mode !== 'formychat') {
        return base
    }
    return mergeCustomDropdownIntoFields(base, form.value)
})

// Form data: keys follow merged FormyChat fields (incl. custom dropdown).
const formData = ref(buildDefaultFormData(formychat_fields.value))

watch(
    formychat_fields,
    (list) => {
        const fresh = buildDefaultFormData(list)
        const merged = { ...fresh }
        Object.keys(fresh).forEach((k) => {
            if (k in formData.value) {
                merged[k] = formData.value[k]
            }
        })
        formData.value = merged
    },
    { deep: true }
)

watch(
    () => props.widget.id,
    () => {
        formData.value = buildDefaultFormData(formychat_fields.value)
    }
)

// Get reCAPTCHA token before submit
const getRecaptchaToken = async () => {
    if (!isRecaptchaEnabled.value) return null
    const rc = typeof formychat_vars !== 'undefined' ? formychat_vars.recaptcha : {}
    if (!rc.site_key) return null
    try {
        if (rc.version === 'v3' && typeof grecaptcha !== 'undefined') {
            return await grecaptcha.execute(rc.site_key, { action: 'submit' })
        }
        if (rc.version === 'v2' && typeof grecaptcha !== 'undefined') {
            return grecaptcha.getResponse() || null
        }
    } catch (e) {
        console.warn('FormyChat reCAPTCHA:', e)
    }
    return null
}

// Submit widget form.
const submitForm = async ( event ) => {
    event.preventDefault()
    state.recaptchaError = null

    const submittedData = { ...formData.value }

    // If country_code is set, concatenate it with phone_number.
    if (submittedData.country_code) {
        submittedData.phone_number = submittedData.country_code + submittedData.phone_number;
    }

    
    const message = getMessage(whatsapp.value.message_template, submittedData);


    const channel = activeChannel.value

    const payload = {
        widget_id: props.widget.id,
        form: 'formychat',
        field: submittedData,
        meta: getMeta.value,
        channel,
    }

    // Get Cloudflare Turnstile token if enabled
    let turnstileToken = null
    if (isTurnstileActive.value) {
        turnstileToken = turnstileResponseToken.value
        if (!turnstileToken) {
            state.recaptchaError = 'Please complete the security verification.'
            return
        }
    }

    // Get reCAPTCHA token if enabled
    let recaptchaToken = null
    if (isRecaptchaEnabled.value) {
        recaptchaToken = await getRecaptchaToken()
        if (!recaptchaToken) {
            state.recaptchaError = 'Please complete the reCAPTCHA verification.'
            return
        }
    }

    // Set sending state to true
    state.sending = true;

    // Submit to ajax.
    const result = await save(payload, null, null, null, null, recaptchaToken, turnstileToken)
    
    // Set sending state to false after save completes
    state.sending = false;

    // Check for save error (e.g. reCAPTCHA verification failed, REST error)
    const isError = result && (result.success === false || (result.response && result.response.status >= 400))
    if (isError) {
        const errData = result?.response?.data || result?.data || {}
        const msg = (typeof errData === 'object' && (errData?.data?.message || errData?.message)) || 'Submission failed. Please try again.'
        state.recaptchaError = msg
        if (isTurnstileActive.value && turnstileWidgetId !== null && typeof window.turnstile !== 'undefined') {
            try {
                window.turnstile.reset(turnstileWidgetId)
            } catch (e) { /* noop */ }
            turnstileResponseToken.value = null
        }
        return
    }

    // Lead is already saved above. Open the chat app unless a listener keeps the visitor here.
    const redirect = shouldRedirect({
        widget: props.widget,
        widget_id: props.widget.id,
        channel,
        lead_id: result?.data?.lead_id || 0,
        message,
        source: 'formychat',
        accent: headerStyle.value.background,
        close: closePopup,
    })

    if (redirect && channel === 'telegram') {
        const url = buildTelegramUrl(telegram.value, message)
        openChannel('telegram', { config: channelConfig.value, text: message })

        // Keep the message on screen, so the visitor is never stuck if the app did not open.
        state.sent = {
            channel,
            message,
            url,
            webUrl: isDesktop() && telegram.value.web_fallback !== false ? buildTelegramWebUrl(telegram.value, message) : '',
        }
    } else if (redirect) {
        if (whatsapp.value.agent_mode === 'agents') {
            openWhatsapp(state.agent.country_code + state.agent.number, message, isDesktop() && whatsapp.value.web_version, whatsapp.value.new_tab, whatsapp.value)
        } else {
            openWhatsapp(whatsappTo.value, message, isDesktop() && whatsapp.value.web_version, whatsapp.value.new_tab, whatsapp.value)
        }
    }

    // Reset form data.
    formData.value = buildDefaultFormData(formychat_fields.value)

    if (isTurnstileActive.value && turnstileWidgetId !== null && typeof window.turnstile !== 'undefined') {
        try {
            window.turnstile.reset(turnstileWidgetId)
        } catch (e) { /* noop */ }
        turnstileResponseToken.value = null
    }

    // The status card stays open for Telegram; a cancelled redirect is confirmed by its listener.
    if (state.sent || !redirect) {
        return
    }

    // Close, if close_on_submit is chosen. When the redirect was cancelled the listener decides.
    if (redirect && form.value.close_on_submit) {
        closePopup()
    } else {
        clearTimeout(state.showingSent)
        state.submitted = true;
        state.errors = [];

        state.showingSent = setTimeout(() => {
            state.submitted = false;
        }, 5000)
    }
}

const copyMessage = async () => {
    if (!state.sent?.message) return
    let copied = false
    try {
        await navigator.clipboard.writeText(state.sent.message)
        copied = true
    } catch (e) {
        // No Clipboard API (sites without HTTPS, older browsers): copy through a hidden textarea.
        const area = document.createElement('textarea')
        area.value = state.sent.message
        area.setAttribute('readonly', '')
        area.style.cssText = 'position:fixed;top:0;left:0;opacity:0;'
        document.body.appendChild(area)
        area.select()
        try { copied = document.execCommand('copy') } catch (err) { copied = false }
        area.remove()
    }
    if (copied) {
        state.copied = true
        setTimeout(() => { state.copied = false }, 2000)
    }
}

const selectAgent = (agent) => {
    if (whatsapp.value.on_click_agent === 'show_form') {
        state.agent = agent
        dispatchEvent('formychat_agent_selected', { widget_id: props.widget.id, agent })
    } else {
        // Redirect to whatsapp.
        openWhatsapp(agent.country_code + agent.number, '', isDesktop() && whatsapp.value.web_version, whatsapp.value.new_tab, whatsapp.value)
        // Hide form.
        closePopup()
    }
}

const form_url = computed(() => {
    let id = form.value[ form.value.mode + '_id'] || form.value.cf7_id;

    let to = whatsapp.value.agent_mode === 'agents' && state.agent ? (state.agent.country_code + state.agent.number) : whatsappTo.value;
   
    return `${formychat_vars.site.url}?formychat-form&form=${form.value.mode}&form_id=${id}&number=${encodeURIComponent(to)}&header=${form.value.subtitle}&footer=${form.value.footer}&widget_id=${props.widget.id}&channel=${activeChannel.value}`;
})

const iFrame = ref(null)
const adjustHeight = (event) => {
    const iframe = event.target;
    
    if (!iframe) return;
    
    // Set initial styles
    iframe.style.transition = 'height 0.1s ease-in-out';
    iframe.style.maxHeight = '100%';
    iframe.style.height = '0px';
    iframe.style.maxHeight = 'calc(100vh - 180px)';
    
    // Wait for iframe content to be fully loaded
    iframe.addEventListener('load', () => {
        // Get the form element height
        const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
        if (!formElement) {
            state.formLoaded = true;  // Using external state object
            dispatchEvent('formychat_form_loaded', { widget_id: props.widget.id, form: form.value.mode || 'cf7', form_id: form.value[form.value.mode + '_id'] || form.value.cf7_id })
            return;
        }
        
        const height = formElement.scrollHeight;
        const newHeight = height + 1;
        
        // Apply the new height with animation
        requestAnimationFrame(() => {
            iframe.style.height = `${newHeight}px`;
            iframe.style.maxHeight = `calc(100vh - 180px)`;
        });
        
        // Reset margin on html element if using CF7
        const htmlElement = iframe.contentWindow.document.querySelector('html');
        if (htmlElement) {
            htmlElement.style.margin = '0';
            htmlElement.style.padding = '0';
        }
    });
    
    // Optional: Handle resize events for responsive forms
    const resizeObserver = new ResizeObserver((entries) => {
        const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
        if (formElement) {
            const newHeight = formElement.scrollHeight + 1;
            iframe.style.height = `${newHeight}px`;
        }
        
        // Set formLoaded after animation using external state
        setTimeout(() => {
            state.formLoaded = true;
            dispatchEvent('formychat_form_loaded', { widget_id: props.widget.id, form: form.value.mode || 'cf7', form_id: form.value[form.value.mode + '_id'] || form.value.cf7_id })
            resizeObserver.disconnect();
        }, 10);
    });
    
    // Start observing the form element for size changes
    const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
    if (formElement) {
        resizeObserver.observe(formElement);
    }
    
    // Cleanup function to disconnect observer when needed
    return () => {
        resizeObserver.disconnect();
    };
};

onMounted(() => {
    window.addEventListener('message', (event) => {
        // event.origin is protocol+host+port only (no path). formychat_vars.site.url may include path.
        const siteOrigin = new URL(formychat_vars.site.url).origin;
        if (event.origin !== siteOrigin) {
            return;
        }

        if (event.data.formychat_submitted) {
            dispatchEvent('formychat_form_submitted', {
                ...event.data.formychat_submitted,
                isWidget: true
            })
            
            adjustHeight({ target: iFrame.value }, false)
            
            // If form should be closed after submit.
            if (form.value.close_on_submit) {
                // For WhatsApp group: wait for user to click OK on copy popup before closing.
                const submittedWidgetId = event.data.formychat_submitted?.widget_id;
                const submittedWidget = submittedWidgetId && formychat_vars.data.widgets?.find(w => w.id == submittedWidgetId);
                const isGroup = submittedWidget?.config?.whatsapp?.destination_type === 'group';
                if (!isGroup) {
                    closePopup()
                    return;
                }
            }

            // Remove header and footer from iFrame.value
            let iFrameDoc = iFrame.value.contentWindow.document;
            iFrameDoc.querySelector('.formychat-header')?.remove();
            iFrameDoc.querySelector('.formychat-footer')?.remove();
        }

        // WhatsApp group: show popup in parent (full viewport) when requested from iframe.
        if (event.data.formychat_show_group_popup) {
            const { url, newTab, widgetId } = event.data.formychat_show_group_popup;
            if (!url || typeof url !== 'string' || !url.startsWith('https://chat.whatsapp.com/')) return;
            if (props.widget.id != widgetId) return;
            const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
            const dismissWithoutNavigate = () => {
                overlay.remove();
                document.removeEventListener('keydown', handleKeydown);
            };
            const openUrl = () => {
                overlay.remove();
                document.removeEventListener('keydown', handleKeydown);
                if (form.value.close_on_submit) closePopup();
                if (newTab && !isSafari) {
                    try {
                        const w = window.open('about:blank', '_blank');
                        if (w) { w.opener = null; w.location.href = url; }
                        else { window.open(url, '_top'); }
                    } catch (e) { window.open(url, '_top'); }
                } else {
                    window.open(url, '_top');
                }
            };
            const overlay = document.createElement('div');
            overlay.setAttribute('role', 'dialog');
            overlay.setAttribute('aria-modal', 'true');
            overlay.setAttribute('aria-labelledby', 'formychat-popup-title');
            overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;font-family:system-ui,sans-serif;';
            overlay.innerHTML = '<div style="background:#fff;border-radius:12px;max-width:400px;width:100%;box-shadow:0 4px 24px rgba(0,0,0,0.15);overflow:visible;">' +
                '<div style="padding:24px 24px 16px;">' +
                '<h2 id="formychat-popup-title" style="margin:0 0 12px;font-size:18px;font-weight:600;color:#1a1a1a;">Message copied!</h2>' +
                '<p style="margin:0 0 16px;font-size:14px;line-height:1.5;color:#4a4a4a;">Your message has been copied to the clipboard. Please paste it manually into the WhatsApp group chat.</p>' +
                '<div style="background:#f5f5f5;border-radius:8px;padding:16px;font-size:13px;line-height:1.6;color:#333;">' +
                '<p style="margin:0 0 8px;font-weight:600;">Desktop:</p>' +
                '<p style="margin:0 0 12px;">Press <kbd style="background:#fff;padding:2px 6px;border-radius:4px;border:1px solid #ddd;">Ctrl+V</kbd> (Windows) or <kbd style="background:#fff;padding:2px 6px;border-radius:4px;border:1px solid #ddd;">Cmd+V</kbd> (Mac) in the message input field.</p>' +
                '<p style="margin:0 0 8px;font-weight:600;">Mobile:</p>' +
                '<p style="margin:0;">Long-press in the message input field and select "Paste".</p>' +
                '</div></div>' +
                '<div style="padding:16px 24px 24px;text-align:right;">' +
                '<button type="button" style="background:#25D366;color:#fff;border:none;padding:10px 24px;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;">Go to WhatsApp</button>' +
                '</div></div>';
            const handleKeydown = (e) => {
                if (e.key === 'Escape') {
                    dismissWithoutNavigate();
                }
            };
            overlay.querySelector('button').addEventListener('click', openUrl);
            overlay.addEventListener('click', (e) => { if (e.target === overlay) dismissWithoutNavigate(); });
            document.addEventListener('keydown', handleKeydown);
            document.body.appendChild(overlay);
            overlay.querySelector('button').focus();
        }
    })
})

// reCAPTCHA / Turnstile — built-in FormyChat form only (global settings from Customize).
const recaptchaConfig = typeof formychat_vars !== 'undefined' ? (formychat_vars.recaptcha || {}) : {}
const turnstileConfig = typeof formychat_vars !== 'undefined' ? (formychat_vars.turnstile || {}) : {}

const isTurnstileActive = computed(() => {
    if (!turnstileConfig.enabled || !turnstileConfig.site_key) return false
    return form.value.mode === 'formychat'
})

const isRecaptchaEnabled = computed(() => {
    if (isTurnstileActive.value) return false
    if (!recaptchaConfig.enabled || !recaptchaConfig.site_key) return false
    return form.value.mode === 'formychat'
})
const recaptchaSiteKey = recaptchaConfig.site_key || ''
const recaptchaVersion = recaptchaConfig.version || 'v2'
const recaptchaContainer = ref(null)
let recaptchaWidgetId = null

const turnstileContainer = ref(null)
const turnstileResponseToken = ref(null)
let turnstileWidgetId = null

const removeTurnstileWidget = () => {
    if (turnstileWidgetId !== null && typeof window.turnstile !== 'undefined') {
        try {
            window.turnstile.remove(turnstileWidgetId)
        } catch (e) { /* noop */ }
    }
    turnstileWidgetId = null
    turnstileResponseToken.value = null
}

const renderTurnstile = () => {
    if (!isTurnstileActive.value || !turnstileContainer.value) return
    const siteKey = turnstileConfig.site_key || ''
    if (!siteKey || typeof window.turnstile === 'undefined') return
    if (turnstileWidgetId !== null) return
    try {
        turnstileWidgetId = window.turnstile.render(turnstileContainer.value, {
            sitekey: siteKey,
            callback: (token) => { turnstileResponseToken.value = token },
            'expired-callback': () => { turnstileResponseToken.value = null },
            'error-callback': () => { turnstileResponseToken.value = null },
        })
    } catch (e) {
        console.warn('FormyChat Turnstile render:', e)
    }
}

const tryRenderTurnstile = () => {
    if (typeof window.turnstile !== 'undefined') {
        renderTurnstile()
    } else {
        setTimeout(tryRenderTurnstile, 100)
    }
}

// Render reCAPTCHA v2 when container is visible
const renderRecaptchaV2 = () => {
    if (recaptchaVersion !== 'v2' || !isRecaptchaEnabled.value || !recaptchaSiteKey) return
    if (!recaptchaContainer.value) return
    if (typeof grecaptcha === 'undefined') return
    if (recaptchaWidgetId !== null) return
    try {
        recaptchaWidgetId = grecaptcha.render(recaptchaContainer.value, {
            sitekey: recaptchaSiteKey,
            theme: 'light',
        })
    } catch (e) {
        console.warn('FormyChat reCAPTCHA render:', e)
    }
}

const tryRenderRecaptcha = () => {
    if (window.formychatRecaptchaReady && typeof grecaptcha !== 'undefined') {
        renderRecaptchaV2()
    } else {
        setTimeout(tryRenderRecaptcha, 100)
    }
}

watch(() => state.showModal, (visible) => {
    if (visible && isRecaptchaEnabled.value && recaptchaVersion === 'v2') {
        recaptchaWidgetId = null
        setTimeout(tryRenderRecaptcha, 50)
    } else if (!visible) {
        recaptchaWidgetId = null
    }
    if (visible && isTurnstileActive.value) {
        removeTurnstileWidget()
        if (turnstileContainer.value) {
            turnstileContainer.value.innerHTML = ''
        }
        setTimeout(tryRenderTurnstile, 50)
    } else if (!visible) {
        removeTurnstileWidget()
    }
})

</script>
