<script setup>
/**
 * Compact "Ultimate" pill shown next to locked settings. Same look as the hover pill in
 * LockedHover. Click opens the upgrade prompt through .formychat-locked.
 */
import { computed } from 'vue';
import { useTranslation } from '@composables/useTranslation';

const { t } = useTranslation();

const props = defineProps({
    /** Omit to show default “Ultimate” label. Pass empty string for icon-only (compact) badges. */
    text: {
        type: String,
        default: undefined,
    },
})

const displayText = computed(() => {
    if (props.text === '') {
        return ''
    }
    if (props.text != null && props.text !== '') {
        return props.text
    }
    return t('ultimate')
})

const isIconOnly = computed(() => displayText.value === '')

const isLocked = computed( () => !formychat_admin_vars.is_premium )
</script>

<template>
    <button
        v-if="isLocked"
        type="button"
        class="formychat-locked formychat-pro-badge"
        :class="{ 'formychat-pro-badge-icon': isIconOnly }"
        :aria-label="isIconOnly ? t('ultimate') : undefined"
        v-bind="$attrs"
    >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <rect x="4.5" y="10.5" width="15" height="10.5" rx="2.5" fill="currentColor" stroke="none" />
            <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
        </svg>
        <span v-if="displayText" v-html="displayText"></span>
    </button>
</template>

